mapper.select:
SELECT r.id AS id, r.goods_id AS goodsId, g.goods_code AS goodsCode, g.name AS goodsName, u.name AS unitName, r.record_type AS recordType, r.change_qty AS changeQty, r.before_qty AS beforeQty, r.after_qty AS afterQty, r.unit_cost AS unitCost, r.biz_type AS bizType, r.biz_no AS bizNo, r.operator_name AS operatorName, r.operate_time AS operateTime, r.remark AS remark FROM inventory_record r JOIN goods g ON g.id = r.goods_id LEFT JOIN unit u ON u.id = g.unit_id
AND r.goods_id = #{q.goodsId}
AND g.name LIKE CONCAT('%', #{q.goodsName}, '%')
AND r.record_type = #{q.recordType}
AND r.biz_no LIKE CONCAT('%', #{q.bizNo}, '%')
AND r.operator_name LIKE CONCAT('%', #{q.operatorName}, '%')
AND r.operate_time >= #{beginTime}
AND r.operate_time < #{endTime}
ORDER BY r.operate_time DESC, r.id DESC
